import {installedPracticeTask} from './practice-queue-entry.js';
import {importWorklist,sourceGroups,worklistPage,MAX_WORKLIST_BYTES,acquisitionGap} from './source-worklist.js';
const $=id=>document.getElementById(id),el=(tag,text)=>{const n=document.createElement(tag);n.textContent=text;return n;};const requestedBucket=new URL(location.href).searchParams.get('bucket');const initialBucket=['held-review-confirmed','expected-acquisition-unresolved','needs-reconciliation'].includes(requestedBucket)?requestedBucket:'all';let worklist=null,page=0,epoch=0,filters={source:'all',kind:'all',bucket:'all',query:''};
let queueSession=crypto.randomUUID();
let queueMode=new URL(location.href).searchParams.get('queue')==='1',currentRows=[];const skipped=new Set(),queueBar=el('div',''),queueStart=el('button','Work held-file queue'),queueSkip=el('button','Skip for now'),queueReset=el('button','Return to skipped'),queueAll=el('button','Show pages');queueBar.className='actions wrap';for(const b of [queueStart,queueSkip,queueReset,queueAll])b.type='button';queueBar.append(queueStart,queueSkip,queueReset,queueAll);$('worklist-rows').before(queueBar);queueStart.onclick=()=>{queueMode=true;page=0;filters.bucket='held-review-confirmed';$('worklist-bucket').value=filters.bucket;render();};queueSkip.onclick=()=>{if(currentRows[0])skipped.add(currentRows[0].id);render();};queueReset.onclick=()=>{skipped.clear();page=0;render();};queueAll.onclick=()=>{queueMode=false;page=0;render();};
function render(){if(!worklist){$('worklist-status').textContent='Choose a private metadata JSON file before applying filters or starting the queue.';for(const b of [queueStart,queueSkip,queueReset,queueAll])b.disabled=true;return;}for(const b of [queueStart,queueSkip,queueReset,queueAll])b.disabled=false;const displayed=queueMode?{...worklist,rows:worklist.rows.filter(r=>r.bucket==='held-review-confirmed'&&!skipped.has(r.id))}:worklist;const result=worklistPage(displayed,{...filters,page,pageSize:queueMode?1:50});currentRows=result.rows;queueStart.hidden=queueMode;queueSkip.hidden=!queueMode;queueSkip.disabled=!result.rows.length;queueAll.hidden=!queueMode;queueReset.disabled=!skipped.size;$('worklist-previous').textContent=queueMode?'Previous item':'Previous page';$('worklist-next').textContent=queueMode?'Next item':'Next page';page=result.page;$('worklist-rows').replaceChildren();for(const r of result.rows){const article=el('article','');article.append(el('h2',r.filename||r.archiveItem||'File identity not recorded'),el('p','Source group: '+r.sourceGroup),el('p','Publisher: '+(r.publisher||'not recorded')+' · download host: '+(r.downloadHost||'not recorded')),el('p','Type: '+r.kind+' · recorded status: '+r.status),el('p','Work bucket: '+r.bucket),el('p',r.possessionBasis),el('p',r.problemSummary),el('p','Version/reference: '+(r.versionReference||'not established')+' · attempt time: '+(r.attemptedAt||'not recorded in this view')),el('p','Evidence: '+r.evidenceSource),el('p','Next human check: '+r.nextCheck),el('p','Location: '+(r.locator||'not established')+' · hash: '+(r.sha256||'not verified')));if(r.url&&acquisitionGap(r)){article.append(el('p','Recorded source URL (reference only): '+r.url),el('p','Inspect existing index evidence and attempt receipts first. This report does not request a download or retry. Shared probe claims and cooldown enforcement are not implemented.'));}else if(r.url){const link=el('a','Open recorded source reference');link.href=r.url;link.target='_blank';link.rel='noopener noreferrer';article.append(el('p','Unverified external reference — destination not checked'),link);}else article.append(el('p','Source URL not established. Resolve the source reference before preparing a correction.'));const practice=installedPracticeTask(r);if(practice){const open=el('a','Open this practice review');open.href='index.html?practice='+encodeURIComponent(practice.id)+'&practiceSession='+queueSession;open.target='_blank';open.rel='noopener';article.append(open);} if(r.sourceGroup==='Bundled synthetic practice'&&!practice)article.append(el('p','No installed exercise link: this row does not match the exact bundled source version. Keep the supplied source and resolve the mismatch.'));$('worklist-rows').append(article);}$('worklist-status').textContent=result.total+' matching metadata records; '+(queueMode?'item ':'page ')+(result.total?page+1:0)+' of '+(result.total?result.pages:0)+'. '+(queueMode?skipped.size+' skipped in this tab only. Skip changes no evidence state. ':'')+'Review type and resolution must be checked before treating these as OCR corrections.';$('worklist-previous').disabled=page===0;$('worklist-next').disabled=page+1>=result.pages;}
$('worklist-file').onchange=async event=>{const file=event.target.files[0];if(!file)return;const ticket=++epoch;try{if(file.size>MAX_WORKLIST_BYTES)throw Error('Choose metadata under 25 MiB');const next=importWorklist(await file.text());if(ticket!==epoch)return;worklist=next;queueSession=crypto.randomUUID();skipped.clear();page=0;filters={source:'all',kind:'all',bucket:initialBucket,query:''};$('worklist-source').replaceChildren(el('option','All sources'));$('worklist-source').firstChild.value='all';for(const [name,count] of sourceGroups(next)){const option=el('option',name+' ('+count+')');option.value=name;$('worklist-source').append(option);}$('worklist-kind').value='all';$('worklist-bucket').value=initialBucket;$('worklist-query').value='';render();}catch(e){if(ticket===epoch)$('worklist-status').textContent=e.message+' Previous displayed list retained.';}finally{event.target.value='';}};
$('worklist-filters').onsubmit=event=>{event.preventDefault();filters={source:$('worklist-source').value,kind:$('worklist-kind').value,bucket:$('worklist-bucket').value,query:$('worklist-query').value};page=0;render();};
$('worklist-previous').onclick=()=>{page--;render();};$('worklist-next').onclick=()=>{page++;render();};

render();
